--
-- Table structure for table `dict_rels`
--

DROP TABLE IF EXISTS `dict_rels`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dict_rels` (
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用（软删除）',
  `id` int NOT NULL AUTO_INCREMENT COMMENT '唯一标识',
  `entity_type` varchar(32) NOT NULL COMMENT '关联实体类型，如 shop / complaint / user 等',
  `entity_id` bigint NOT NULL COMMENT '关联实体主键 ID',
  `dict_data_id` int NOT NULL COMMENT '字典数据ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uid_dict_rels_entity__516ed8` (`entity_type`,`entity_id`,`dict_data_id`),
  KEY `fk_dict_rel_dict_dat_731bf834` (`dict_data_id`),
  CONSTRAINT `fk_dict_rel_dict_dat_731bf834` FOREIGN KEY (`dict_data_id`) REFERENCES `dict_data` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=187 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='DictRel 表 — 字典数据关联表（多态）';
/*!40101 SET character_set_client = @saved_cs_client */;

